mapper.insert:
insert into oa_company_seal_config (
    legal_entity_id, seal_code, seal_name, seal_type, is_default,
    seal_image_url, seal_image_hash, valid_from, valid_to,
    status, create_by, create_time, remark
) values (
    #{legalEntityId}, #{sealCode}, #{sealName}, #{sealType}, #{isDefault},
    #{sealImageUrl}, #{sealImageHash}, #{validFrom}, #{validTo},
    #{status}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update oa_company_seal_config
legal_entity_id = #{legalEntityId}, seal_code = #{sealCode}, seal_name = #{sealName}, seal_type = #{sealType}, is_default = #{isDefault}, seal_image_url = #{sealImageUrl}, seal_image_hash = #{sealImageHash}, valid_from = #{validFrom}, valid_to = #{validTo}, status = #{status}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where seal_id = #{sealId}

mapper.select:
select s.seal_id, s.legal_entity_id, le.legal_entity_name, s.seal_code, s.seal_name, s.seal_type, s.is_default, s.seal_image_url, s.seal_image_hash, s.valid_from, s.valid_to, s.status, s.create_by, s.create_time, s.update_by, s.update_time, s.remark from oa_company_seal_config s inner join sys_legal_entity le on le.legal_entity_id = s.legal_entity_id where s.legal_entity_id = #{legalEntityId}
and s.status = '0' and (s.valid_from is null or s.valid_from <= sysdate()) and (s.valid_to is null or s.valid_to >= sysdate())
order by s.is_default desc, s.seal_name asc, s.seal_id asc

mapper.update:
update oa_company_seal_config
set is_default = 'N', update_time = sysdate()
where legal_entity_id = #{legalEntityId}
  and is_default = 'Y'
  and seal_id != #{exceptSealId}
